mapper.select:
select COLUMN_NAME
from user_tab_columns
where Table_Name = #{tableName,jdbcType=VARCHAR}

mapper.delete:
	delete from CHB_ASSETS_BASIS_DATA_CHILD 
	where  1=1
	and DATA_SOURCE = '16'/*为避免误删除业务数据维护导入的数据，增加此条件*/

     and value_date = #{valueDate,jdbcType=DATE}


    and PROD_ID = #{prodId,jdbcType=VARCHAR}


     and ASSET_ID = #{assetId,jdbcType=VARCHAR}

		 begin

	     delete from CHB_ASSETS_BASIS_DATA
	     where ASSET_ID = #{item.assetId,jdbcType=VARCHAR}  and VALUE_DATE = #{item.valueDate,jdbcType=TIMESTAMP}
	     	and PROD_ID = #{item.prodId,jdbcType=VARCHAR}

    	;end;
